{
  "slug": "ken-burns",
  "name": "Ken Burns",
  "subtitle": "Pan and zoom image animation for documentaries and slideshows",
  "description": [
    "Applies a slow pan-and-zoom (Ken Burns) effect to an image or content layer using interpolate() on scale and translate, creating the signature documentary-style motion. Use it for photo slideshows, historical footage segments, or any scene that needs cinematic image movement.",
    "Zoom range, pan direction, and animation duration are configurable. The effect is frame-driven and deterministic, producing identical output in browser preview and server-side renders."
  ],
  "category": "Cinematic",
  "tier": "free",
  "duration": 90,
  "fps": 30,
  "isNew": false,
  "author": "React Video Editor",
  "authorLink": "https://www.reactvideoeditor.com",
  "page": "https://www.reactvideoeditor.com/remotion-templates/ken-burns",
  "sourceCode": ""use client";
import React from "react";

interface KenBurnsProps {
  imageUrl?: string;
  duration?: number;
  scale?: number;
  translateX?: number;
  translateY?: number;
}

export const KenBurns: React.FC<KenBurnsProps> = ({
  imageUrl = "https://images.unsplash.com/photo-1682687220742-aba13b6e50ba",
  duration = 20,
  scale = 1.5,
  translateX = -50,
  translateY = -30,
}) => {
  return (
    <div
      style={{
        flex: 1,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        backgroundColor: "black",
        overflow: "hidden",
      }}
    >
      <img
        src={imageUrl}
        style={{
          width: "100%",
          height: "100%",
          objectFit: "cover",
          animation: `kenBurns ${duration}s ease-out forwards`,
        }}
      />
      <style jsx>{`
        @keyframes kenBurns {
          0% {
            transform: scale(1) translate(0, 0);
          }
          100% {
            transform: scale(${scale})
              translate(${translateX}px, ${translateY}px);
          }
        }
      `}</style>
    </div>
  );
};

export default KenBurns;
"
}
